
-- Handbook v1.14 remediation: distinct study, recovery, household, and coordination events.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'translated record' WHEN 1 THEN 'translated record' WHEN 2 THEN 'translated record'
      WHEN 3 THEN 'translated record' WHEN 4 THEN 'translated record' WHEN 5 THEN 'translated record'
      WHEN 6 THEN 'translated record' WHEN 7 THEN 'translated recordstepstranslated record' WHEN 8 THEN 'translated record'
      WHEN 9 THEN 'follow-up appointmenttranslated record' WHEN 10 THEN 'translated record' WHEN 11 THEN 'translated record'
      WHEN 12 THEN 'translated record' WHEN 13 THEN 'translated record' WHEN 14 THEN 'translated recordemailtranslated record'
      WHEN 15 THEN 'budgettranslated record' ELSE 'translated record' END AS event_topic,
    CASE rowid % 19
      WHEN 0 THEN 'translated record' WHEN 1 THEN 'translated record' WHEN 2 THEN 'translated recordhospitalfollow-up appointmenttranslated record' WHEN 3 THEN 'translated record'
      WHEN 4 THEN 'paintranslated record' WHEN 5 THEN 'translated record' WHEN 6 THEN 'translated record' WHEN 7 THEN 'translated record'
      WHEN 8 THEN 'translated record' WHEN 9 THEN 'translated record' WHEN 10 THEN 'translated recordsteps' WHEN 11 THEN 'translated record'
      WHEN 12 THEN 'translated recordbudget' WHEN 13 THEN 'translated record' WHEN 14 THEN 'translated record' WHEN 15 THEN 'translated record'
      WHEN 16 THEN 'translated record Notion' WHEN 17 THEN 'translated record' ELSE 'translated recordZhang Mingtranslated record' END AS event_constraint
  FROM events WHERE event_id LIKE 'cal_noise_%'
)
UPDATE events
SET summary=(SELECT event_topic FROM facts WHERE facts.rid=events.rowid),
    description=CASE rowid % 7
      WHEN 0 THEN (SELECT event_topic || 'translated record；' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 1 THEN (SELECT 'translated record' || event_topic || '，translated record' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 2 THEN (SELECT event_constraint || '；translated record' || event_topic || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 3 THEN (SELECT 'translated record：' || event_topic || '。' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 4 THEN (SELECT event_topic || 'translated record；' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      WHEN 5 THEN (SELECT 'translated record' || event_topic || '；translated record' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
      ELSE (SELECT event_topic || 'translated record，translated record' || event_constraint || '。' FROM facts WHERE facts.rid=events.rowid)
    END,
    event_id=replace(event_id,'cal_noise_','cal_context_')
WHERE event_id LIKE 'cal_noise_%';
